require('./backend/node_modules/dotenv').config({path:'backend/.env',quiet:true});
const mongoose=require('./backend/node_modules/mongoose');mongoose.set('autoIndex',false);
const {buildMongoUri,mongoConfig}=require('./backend/src/config/mongoConfig');
(async()=>{const cfg=mongoConfig();await mongoose.connect(buildMongoUri(),{dbName:cfg.dbName,authSource:cfg.authSource,serverSelectionTimeoutMS:10000,autoIndex:false,compressors:['zlib'],zlibCompressionLevel:1});
const user=await require('./backend/src/models/User').findOne({isActive:true,role:'admin'}).select('_id name email role roles').lean();
const token=require('./backend/node_modules/jsonwebtoken').sign({sub:String(user._id)},process.env.JWT_SECRET||'secret',{expiresIn:60});
const Module=require('module'),path=require('path');function patch(file,source){const filename=path.resolve(file);const m=new Module(filename,module);m.filename=filename;m.paths=Module._nodeModulePaths(path.dirname(filename));require.cache[filename]=m;m._compile(Buffer.from(source,'base64').toString('utf8'),filename);return m.exports;}
globalThis.__snapshots=patch('backend/src/services/compactReadSnapshot.js','');
const leadController=patch('backend/src/controllers/leadController.js','');
const leadRevenueController=patch('backend/src/controllers/leadRevenueController.js','');
for(let run=1;run<=1;run++){for(const [label,fn,query] of [['po',leadController.listDuplicateLeadApprovals,{listOnly:'true',type:'purchase_order'}],['summary',leadRevenueController.pipeline,{}]]){let at=Date.now();const headers={};await fn({user,query},{set(k,v){headers[k]=v;return this;},json(body){console.log(JSON.stringify({run,label,ms:Date.now()-at,rows:body.rows?.length||body.approvals?.length,bytes:JSON.stringify(body).length,timing:headers['Server-Timing']}));}},error=>{throw error;});}}

await mongoose.disconnect();process.exit(0);})().catch(e=>{console.error('verification_failed',e.name,e.code);process.exit(1);});
